      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Reported hearing changes and associated symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Longstanding bilateral sensorineural hearing loss with behind-the-ear hearing aids; reports hearing has 'gone down another notch' and television is louder, with husband complaining. Hearing feels worse and more blocked when nose is congested during the current head cold. No unilateral symptoms, sudden loss, vertigo, new tinnitus, ear fullness or otalgia. Occasionally forgets to wear hearing aids because they whistle with grandchildren. Last audiology approximately 2 years ago; no recent ear wax removal."
      }
    },
