      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Bedside hearing assessment"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Conversational voice heard at 1–2 m with hearing aids in; occasional repetition needed, especially with corridor noise. Whisper test less reliable due to anxiety and background noise. Overall picture consistent with known bilateral sensorineural hearing loss; no obvious asymmetry."
      }
    },
